import ast, os, re
from collections import defaultdict

# Find .py files that are NEVER imported by any other file
py_files = set()
for root, dirs, files in os.walk('nanobot'):
    for f in files:
        if f.endswith('.py'):
            py_files.add(os.path.join(root, f))

# Collect all import targets
imported_files = set()
for fpath in py_files:
    try:
        with open(fpath) as f:
            content = f.read()
        tree = ast.parse(content)
    except:
        continue
    for node in ast.walk(tree):
        if isinstance(node, ast.ImportFrom) and node.module:
            # Convert module path to possible file paths
            mod = node.module
            # Check if any alias matches a file
            for alias in (node.names or []):
                name = alias.name
                # Could be: from nanobot.channels.telegram import formatting
                # -> nanobot/channels/telegram/formatting.py
                possible = mod + '.' + name
                possible_file = possible.replace('.', '/') + '.py'
                if possible_file in py_files:
                    imported_files.add(possible_file)
                # Also check module itself
                mod_file = mod.replace('.', '/') + '.py'
                if mod_file in py_files:
                    imported_files.add(mod_file)
        elif isinstance(node, ast.Import):
            for alias in node.names:
                mod_file = alias.name.replace('.', '/') + '.py'
                if mod_file in py_files:
                    imported_files.add(mod_file)

# Also check __init__.py files for dynamic imports
for fpath in py_files:
    if fpath.endswith('__init__.py'):
        try:
            with open(fpath) as f:
                content = f.read()
        except:
            continue
        # Check for dynamic patterns like __import__, importlib, etc.
        if any(kw in content for kw in ['importlib', '__import__', 'import_module']):
            # This __init__ dynamically imports - mark sibling files as imported
            parent = os.path.dirname(fpath)
            for pf in py_files:
                if os.path.dirname(pf) == parent and pf != fpath:
                    imported_files.add(pf)

# Find never-imported files (excluding __init__.py, __main__.py, scripts, test files)
never_imported = []
for fpath in sorted(py_files):
    if fpath in imported_files:
        continue
    if '__init__.py' in fpath or '__main__.py' in fpath:
        continue
    if '/scripts/' in fpath or '/test_' in fpath:
        continue
    # Check if it's a channel plugin (loaded dynamically)
    if '/channels/' in fpath and fpath.endswith('.py') and '__init__' not in fpath:
        continue
    never_imported.append(fpath)

print(f'Total .py files: {len(py_files)}')
print(f'Imported files: {len(imported_files)}')
print(f'Never imported (excluding entry points): {len(never_imported)}')
print()
for f in never_imported:
    lines = 0
    try:
        with open(f) as fh:
            lines = sum(1 for _ in fh)
    except:
        pass
    print(f'  {f} ({lines} lines)')
